window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz57ohr"]=[
["0","Преамбула и список изменений","","2026-06-10","РОССИЙСКАЯ ФЕДЕРАЦИЯ ФЕДЕРАЛЬНЫЙ ЗАКОН О государственной охране\nПринят Государственной Думой 24 апреля 1996 года\nОдобрен Советом Федерации 15 мая 1996 года\nСписок изменяющих документов(В редакции федеральных законов от 18.07.1997 № 101-ФЗ, от 07.11.2000 № 135-ФЗ, от 07.05.2002 № 49-ФЗ, от 30.06.2003 № 86-ФЗ, от 22.08.2004 № 122-ФЗ, от 29.12.2004 № 191-ФЗ, от 26.06.2007 № 118-ФЗ, от 04.12.2007 № 328-ФЗ, от 14.07.2008 № 118-ФЗ, от 28.12.2010 № 404-ФЗ, от 08.12.2011 № 424-ФЗ, от 02.07.2013 № 185-ФЗ, от 25.11.2013 № 317-ФЗ, от 12.03.2014 № 29-ФЗ, от 03.07.2016 № 227-ФЗ, от 18.06.2017 № 127-ФЗ, от 01.07.2017 № 148-ФЗ, от 07.03.2018 № 56-ФЗ, от 02.12.2019 № 404-ФЗ, от 27.12.2019 № 447-ФЗ, от 01.04.2020 № 92-ФЗ, от 30.04.2021 № 116-ФЗ, от 14.07.2022 № 278-ФЗ, от 04.08.2022 № 363-ФЗ, от 04.08.2023 № 440-ФЗ, от 08.08.2024 № 271-ФЗ, от 28.02.2025 № 23-ФЗ, от 01.04.2025 № 41-ФЗ, от 10.06.2026 № 177-ФЗ)\nНастоящий Федеральный закон определяет предназначение государственной охраны, основные принципы и содержание деятельности по осуществлению государственной охраны, полномочия и функции органов государственной охраны, а также порядок контроля и надзора за их деятельностью. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["1","Основные понятия","","2020-04-01","Статья 1. Основные понятия\nВ настоящем Федеральном законе применяются следующие основные понятия:\nгосударственная охрана - деятельность по обеспечению безопасности объектов государственной охраны и защите охраняемых объектов, выполняемая в целях обеспечения безопасности Российской Федерации, безопасного и беспрепятственного осуществления государственной власти в Российской Федерации и исполнения международных обязательств Российской Федерации, осуществляемая на основе совокупности правовых, организационных, охранных, режимных, оперативно-розыскных, технических, информационных и иных мер; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.04.2020 № 92-ФЗ)\nобъекты государственной охраны - лица, подлежащие государственной охране в соответствии с настоящим Федеральным законом;\nохраняемые объекты - здания, строения, сооружения (в том числе отдельные помещения), прилегающие к ним земельные участки (водные объекты), территории (акватории), защита которых осуществляется органами государственной охраны в целях обеспечения безопасности объектов государственной охраны; здания, строения, сооружения (в том числе отдельные помещения), земельные участки и водные объекты, предоставленные органам государственной охраны в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 01.07.2017 № 148-ФЗ)\nохранное мероприятие - совокупность действий, направленных на обеспечение безопасности объекта государственной охраны и осуществляемых органами государственной охраны самостоятельно или с привлечением государственных органов, участвующих в пределах своих полномочий в обеспечении государственной охраны; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.04.2020 № 92-ФЗ)\nпропускной режим - комплекс мер, осуществляемых органами государственной охраны самостоятельно или совместно с владельцем (пользователем) охраняемого объекта и связанных с организацией доступа на охраняемый объект, передвижением физических лиц, транспортных средств на охраняемом объекте, проносом и провозом вещей (грузов) на охраняемый объект или выносом и вывозом вещей (грузов) с охраняемого объекта; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nзона охраняемого объекта - территория (акватория), в границах которой в соответствии с федеральным законодательством устанавливаются особые условия ее использования; (Дополнение абзацем - Федеральный закон от 29.12.2004 № 191-ФЗ) (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nбезопасность объекта государственной охраны - состояние защищенности лица, подлежащего государственной охране, от противоправных и иных посягательств, угрожающих его жизни, здоровью и иным охраняемым законом жизненно важным интересам, связанным с исполнением полномочий государственной власти либо с иной государственной, политической или общественной деятельностью; (Дополнение абзацем - Федеральный закон от 08.12.2011 № 424-ФЗ)\nзащита охраняемого объекта - совокупность мероприятий по охране и обороне охраняемого объекта, осуществляемых органами государственной охраны самостоятельно или с привлечением государственных органов, участвующих в пределах своих полномочий в обеспечении государственной охраны; (Дополнение абзацем - Федеральный закон от 08.12.2011 № 424-ФЗ) (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\nтрассы проезда (передвижения) объектов государственной охраны - участки автомобильных, железных дорог, воздушного, водного пространства, используемые для безопасного и беспрепятственного проезда (передвижения) объектов государственной охраны. (Дополнение абзацем - Федеральный закон от 08.12.2011 № 424-ФЗ)"],
["2","Правовая основа государственной охраны","","","Статья 2. Правовая основа государственной охраны\nГосударственная охрана осуществляется на основе Конституции Российской Федерации, федеральных конституционных законов, настоящего Федерального закона, других федеральных законов и иных нормативных правовых актов Российской Федерации, а также международных договоров Российской Федерации."],
["3","Основные принципы осуществления государственной охраны","","2020-04-01","Статья 3. Основные принципы осуществления государственной охраны\nГосударственная охрана осуществляется на основе следующих принципов:\nзаконности;\nуважения и соблюдения прав и свобод человека и гражданина;\nцентрализованного руководства;\nвзаимодействия органов государственной охраны с другими государственными органами, органами местного самоуправления и организациями; (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\nнепрерывности, системности и комплексности применения правовых, организационных, охранных, режимных, оперативно-розыскных, технических, информационных и иных мер; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nсочетания гласных и негласных методов деятельности;\nподконтрольности и поднадзорности;\nприоритета предупредительных мер. (Дополнение абзацем - Федеральный закон от 08.12.2011 № 424-ФЗ)"],
["4","Меры по осуществлению государственной охраны","","2017-07-01","Статья 4. Меры по осуществлению государственной охраны\nГосударственная охрана осуществляется на основе следующих мер:\n1) предоставление объекту государственной охраны персональной охраны, связи для нужд органов государственной власти, информации об угрозе его безопасности, транспортного обслуживания, бытового обслуживания и обеспечения, безопасного питания, а также обеспечение его санитарно-эпидемиологического благополучия; (В редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n2) предупреждение, выявление и пресечение преступных и иных противоправных посягательств на объекты государственной охраны и охраняемые объекты;\n3) проведение мероприятий, обеспечивающих поддержание общественного порядка на охраняемых объектах, а также на трассах проезда (передвижения) объектов государственной охраны;\n4) защита охраняемых объектов, обеспечение на охраняемых объектах пропускного и внутриобъектового режимов;\n5) организация связи для нужд органов государственной власти, обеспечение надежного функционирования и информационной безопасности связи при ее предоставлении Президенту Российской Федерации, Правительству Российской Федерации, иным государственным органам, в том числе в военное время и при чрезвычайных ситуациях;\n6) организация федеральных информационных систем для информационно-технологического и информационно-аналитического обеспечения деятельности Президента Российской Федерации, Правительства Российской Федерации, иных государственных органов, а также обеспечение надежного функционирования этих систем и их информационной безопасности, в том числе в военное время и при чрезвычайных ситуациях.\n(Статья в редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["5","Органы, осуществляющие государственную охрану и участвующие в ее обеспечении","","2020-04-01","Статья 5. Органы, осуществляющие государственную охрану и участвующие в ее обеспечении\n(Наименование в редакции Федерального закона от 01.04.2020 № 92-ФЗ)\nГосударственную охрану осуществляют органы государственной охраны. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nВ обеспечении государственной охраны в пределах своих полномочий участвуют федеральные органы исполнительной власти в области обороны, в области обеспечения безопасности, в сфере внутренних дел, в сфере внешней разведки, в сфере деятельности войск национальной гвардии Российской Федерации, федеральный орган исполнительной власти, уполномоченный на решение задач в области гражданской обороны. (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)"],
["6","Объекты государственной охраны","","2011-12-08","Статья 6. Объекты государственной охраны\nК объектам государственной охраны относятся Президент Российской Федерации, определенные настоящим Федеральным законом лица, замещающие государственные должности Российской Федерации, федеральные государственные служащие и иные лица, подлежащие государственной охране в соответствии с настоящим Федеральным законом, а также главы иностранных государств и правительств и иные лица иностранных государств во время пребывания на территории Российской Федерации. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["7","Предоставление государственной охраны Президенту Российской Федерации","","2011-12-08","Статья 7. Предоставление государственной охраны Президенту Российской Федерации\n1. Президенту Российской Федерации со дня официального опубликования общих результатов выборов Президента Российской Федерации предоставляется государственная охрана в полном объеме мер, предусмотренных статьей 4 настоящего Федерального закона. Президент Российской Федерации в течение срока своих полномочий не вправе отказаться от государственной охраны.\n2. Президенту Российской Федерации, прекратившему исполнение своих полномочий, государственная охрана предоставляется в соответствии с федеральным законодательством.\n3. В течение срока полномочий Президента Российской Федерации государственная охрана предоставляется членам его семьи, проживающим совместно с ним или сопровождающим его.\n(Статья в редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["8","Предоставление государственной охраны лицам, замещающим государственные должности Российской Федерации","","2014-03-12","Статья 8. Предоставление государственной охраны лицам, замещающим государственные должности Российской Федерации\nГосударственная охрана предоставляется следующим лицам, замещающим государственные должности Российской Федерации:\nПредседателю Правительства Российской Федерации;\nПредседателю Совета Федерации Федерального Собрания Российской Федерации;\nПредседателю Государственной Думы Федерального Собрания Российской Федерации;\nПредседателю Конституционного Суда Российской Федерации;\nПредседателю Верховного Суда Российской Федерации;\nАбзац; (Утратил силу - Федеральный закон от 12.03.2014 № 29-ФЗ)\nГенеральному прокурору Российской Федерации;\nПредседателю Следственного комитета Российской Федерации. (Дополнение абзацем - Федеральный закон от 28.12.2010 № 404-ФЗ)\nУказанным лицам государственная охрана предоставляется в течение срока их полномочий."],
["9","Предоставление государственной охраны сенаторам Российской Федерации, депутатам Государственной Думы Федерального Собрания Российской Федерации, федеральным государственным служащим и иным лицам","","2022-08-04","Статья 9. Предоставление государственной охраны сенаторам Российской Федерации, депутатам Государственной Думы Федерального Собрания Российской Федерации, федеральным государственным служащим и иным лицам\nВ целях обеспечения безопасности государства по решению Президента Российской Федерации государственная охрана может быть предоставлена сенаторам Российской Федерации, депутатам Государственной Думы Федерального Собрания Российской Федерации, федеральным государственным служащим и иным лицам.\n(Статья в редакции Федерального закона от 04.08.2022 № 363-ФЗ)"],
["10","Порядок предоставления государственной охраны","","2011-12-08","Статья 10. Порядок предоставления государственной охраны\nПорядок предоставления государственной охраны лицам, указанным в статьях 8 и 9 настоящего Федерального закона, определяется Президентом Российской Федерации.\n(Статья в редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["11","Предоставление государственной охраны главам иностранных государств и правительств и иным лицам иностранных государств","","2020-04-01","Статья 11. Предоставление государственной охраны главам иностранных государств и правительств и иным лицам иностранных государств\n(Наименование в редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n1. Государственная охрана предоставляется главам иностранных государств и правительств, а также сопровождающим их членам семей в период пребывания на территории Российской Федерации в соответствии с международными договорами Российской Федерации. (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n2. При необходимости по решению Президента Российской Федерации государственная охрана предоставляется иным иностранным государственным, политическим и общественным деятелям в период пребывания на территории Российской Федерации. (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n3. Порядок предоставления государственной охраны лицам, указанным в настоящей статье, определяется Президентом Российской Федерации. (Дополнение пунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)"],
["12","Органы государственной охраны","","2013-07-02","Статья 12. Органы государственной охраны\n1. К органам государственной охраны относится федеральный орган исполнительной власти в области государственной охраны, а также подразделения федерального органа исполнительной власти в области государственной охраны, осуществляющие отдельные полномочия указанного органа (далее - подразделения), и военные профессиональные образовательные организации и военные образовательные организации высшего образования федерального органа исполнительной власти в области государственной охраны. Подразделения могут являться юридическими лицами. (В редакции Федерального закона от 02.07.2013 № 185-ФЗ)\nВ ведении федерального органа исполнительной власти в области государственной охраны могут находиться научные организации, образовательные организации и иные организации. (В редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n2. Руководство федеральным органом исполнительной власти в области государственной охраны осуществляет Президент Российской Федерации.\n3. Создание, реорганизацию и упразднение федерального органа исполнительной власти в области государственной охраны осуществляет Президент Российской Федерации в соответствии с федеральным законодательством.\n4. Положение о федеральном органе исполнительной власти в области государственной охраны утверждает Президент Российской Федерации.\n(Статья в редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["13","Основные задачи органов государственной охраны","","2026-06-10","Статья 13. Основные задачи органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nОсновными задачами органов государственной охраны являются: (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1) прогнозирование и выявление угрозы безопасности объектов государственной охраны и охраняемых объектов, осуществление комплекса мер по предотвращению этой угрозы; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 10.06.2026 № 177-ФЗ)\n2) обеспечение безопасности объектов государственной охраны; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n3) обеспечение в пределах своих полномочий организации и функционирования связи для нужд органов государственной власти; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n4) участие в пределах своих полномочий в борьбе с терроризмом;\n5) обеспечение защиты охраняемых объектов; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n6) выявление, предупреждение и пресечение преступлений и иных правонарушений на охраняемых объектах и на трассах проезда (передвижения) объектов государственной охраны; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n7) обеспечение организации и функционирования федеральных информационных систем, находящихся во владении или в пользовании органов государственной охраны; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n8) участие в пределах своих полномочий в обеспечении информационной безопасности Российской Федерации; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n9) обеспечение защиты персональных данных объектов государственной охраны и членов их семей. (Дополнение подпунктом - Федеральный закон от 01.07.2017 № 148-ФЗ)"],
["14","Обязанности органов государственной охраны","","2019-12-27","Статья 14. Обязанности органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nОрганы государственной охраны обязаны: (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1) выявлять, предупреждать и пресекать преступные и иные противоправные посягательства на объекты государственной охраны и охраняемые объекты; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n2) организовывать и проводить охранные, режимные, технические и иные мероприятия по обеспечению безопасности объектов государственной охраны на охраняемых объектах и на трассах проезда (передвижения) объектов государственной охраны; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n2.1) организовывать и осуществлять в пределах своих полномочий транспортное обслуживание, бытовое обслуживание и обеспечение, безопасное питание, а также обеспечение санитарно-эпидемиологического благополучия объектов государственной охраны; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n2.2) осуществлять на охраняемых объектах инструментально-техническую и лабораторную диагностику, эвакуацию и уничтожение материальных объектов (предметов), вызывающих подозрение в принадлежности к взрывчатым веществам и диверсионно-террористическим средствам (включая биологические) или устройствам для несанкционированного доступа к информации; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n3) поддерживать общественный порядок, необходимый для обеспечения безопасности объектов государственной охраны на охраняемых объектах и на трассах проезда (передвижения) объектов государственной охраны, принимать меры по устранению обстоятельств, препятствующих осуществлению государственной охраны; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n4) обеспечивать в необходимых случаях сопровождение транспортных средств, в которых следуют объекты государственной охраны; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5) организовывать и проводить в пределах своих полномочий мероприятия по развитию и совершенствованию связи для нужд органов государственной власти, обеспечению ее надежности, информационной безопасности и оперативности при предоставлении Президенту Российской Федерации, Правительству Российской Федерации, иным государственным органам, а при необходимости органам местного самоуправления и организациям. Порядок обеспечения связью для нужд органов государственной власти устанавливается нормативными правовыми актами Президента Российской Федерации; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5.1) осуществлять в порядке, установленном нормативными правовыми актами Президента Российской Федерации, разработку, создание, эксплуатацию и развитие федеральных информационных систем для информационно-технологического и информационно-аналитического обеспечения деятельности Президента Российской Федерации, Правительства Российской Федерации, иных государственных органов, обеспечивать надежное функционирование этих систем и их информационную безопасность, в том числе в военное время и при чрезвычайных ситуациях, участвовать в формировании государственных информационных ресурсов, организации их резервирования и осуществлении государственной политики в области правовой информатизации Российской Федерации; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n6) организовывать и выполнять шифровальные работы; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n7) организовывать и осуществлять на охраняемых объектах и на трассах проезда (передвижения) объектов государственной охраны оперативно-технический, радиотехнический, химический, радиационный, экологический, противоэпидемический, санитарно-гигиенический контроль, а также контроль за обеспечением пожарной безопасности и федеральный государственный ветеринарный надзор; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 27.12.2019 № 447-ФЗ)\n7.1) осуществлять на охраняемых объектах, находящихся в оперативном управлении органов государственной охраны, ветеринарное обслуживание животных; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n7.2) осуществлять в пределах своих полномочий контроль за соблюдением требований нормативных правовых актов Российской Федерации, регламентирующих порядок использования для нужд органов государственной власти сетей связи специального назначения, и за соблюдением порядка использования радиочастотного спектра; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n8) осуществлять информационно-аналитическое обеспечение своей деятельности;\n9) обеспечивать собственную безопасность;\n10) осуществлять во взаимодействии с органами федеральной службы безопасности меры по противодействию утечке информации по техническим каналам; (В редакции Федерального закона от 30.06.2003 № 86-ФЗ)\n11) обеспечивать и (или) осуществлять профессиональное обучение, профессиональное образование и дополнительное профессиональное образование; (В редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n12) осуществлять служебно-хозяйственную деятельность;\n13) осуществлять внешние сношения со специальными службами, с правоохранительными органами и организациями иностранных государств."],
["15","Права органов государственной охраны","","2025-04-01","Статья 15. Права органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nОрганы государственной охраны в целях осуществления государственной охраны имеют право: (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1) привлекать государственные органы, участвующие в пределах своих полномочий в обеспечении государственной охраны, к подготовке и проведению охранных мероприятий или защите охраняемых объектов; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.04.2020 № 92-ФЗ)\n2) осуществлять оперативно-розыскную деятельность в соответствии с федеральным законодательством об оперативно-розыскной деятельности;\n3) осуществлять проверку документов, удостоверяющих личность, а также документов на транспортные средства и перевозимые грузы; производить при проходе (проезде) лиц на охраняемые объекты и при их выходе (выезде) с охраняемых объектов личный досмотр (осмотр), досмотр (осмотр) находящихся при них вещей, досмотр (осмотр) транспортных средств и перевозимых грузов, в том числе с применением технических средств и служебных животных; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n3.1) определять перечень вещей (грузов), запрещенных к проносу и провозу на охраняемые объекты; (Дополнение подпунктом - Федеральный закон от 01.07.2017 № 148-ФЗ)\n3.2) определять трассы проезда (передвижения) объектов государственной охраны; (Дополнение подпунктом - Федеральный закон от 01.04.2020 № 92-ФЗ)\n4) производить документирование, фотографирование, звукозапись, кино- и видеосъемку фактов и событий;\n5) задерживать и доставлять в служебное помещение органа внутренних дел (полиции), помещение муниципального органа или в иное служебное помещение лиц, подозреваемых в совершении преступлений или иных правонарушений на охраняемых объектах и на трассах проезда (передвижения) объектов государственной охраны, совершающих или совершивших такие преступления или правонарушения; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5.1) осуществлять производство по делам об административных правонарушениях, отнесенным Кодексом Российской Федерации об административных правонарушениях к подведомственности федерального органа исполнительной власти в области государственной охраны; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n5.2) осуществлять проверку подготовки уполномоченными транспортными организациями предоставляемых объектам государственной охраны специально оборудованных транспортных средств, в том числе проверку соблюдения порядка и правил их эксплуатации; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n6) вносить в органы государственной власти, органы местного самоуправления, организации, общественные объединения обязательные для исполнения представления об устранении причин и условий, порождающих угрозу безопасности объектов государственной охраны и охраняемых объектов.\nПорядок внесения таких представлений и полномочия должностных лиц органов государственной охраны по их внесению устанавливаются руководителем федерального органа исполнительной власти в области государственной охраны.\nМеры по устранению причин и условий, порождающих угрозу безопасности объектов государственной охраны и охраняемых объектов, принимаются незамедлительно.\nОрганы государственной власти, органы местного самоуправления, организации, общественные объединения в течение одного месяца со дня получения представления информируют органы государственной охраны об устранении причин и условий, порождающих угрозу безопасности объектов государственной охраны и охраняемых объектов;\n(Подпункт в редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n7) использовать в служебных целях средства связи, включая и специальные, принадлежащие организациям, а в неотложных случаях и гражданам; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n7.1) получать в организациях беспрепятственный доступ для производства работ, обеспечивающих функционирование и безопасность линий и средств связи, оборудования федеральных информационных систем, находящихся во владении или в пользовании органов государственной охраны, и необходимую техническую документацию; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n7.2) налагать в установленном нормативными правовыми актами Российской Федерации порядке ограничения на использование радиоэлектронных средств и высокочастотных устройств любого назначения, если они создают радиопомехи связи для нужд органов государственной власти; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n8) использовать в служебных целях транспортные средства, принадлежащие организациям, за исключением транспортных средств дипломатических, консульских и иных представительств иностранных государств и международных организаций, а в неотложных случаях и гражданам, для предотвращения преступлений, для преследования и задержания лица, совершившего преступление или подозреваемого в его совершении, для доставления лица, нуждающегося в срочной медицинской помощи, в лечебное учреждение, а также для проезда к месту происшествия с возможным отстранением водителей от управления этими средствами. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nОрганы государственной охраны по требованию владельцев транспортных средств возмещают причиненный им реальный ущерб в порядке, установленном федеральным законодательством; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n8.1) использовать на безвозмездной основе аэропорты, аэродромы, вертодромы, посадочные площадки, морские, речные порты независимо от их организационно-правовых форм и форм собственности, а также получать на безвозмездной основе обеспечение полетов и судовождения; (Дополнение подпунктом - Федеральный закон от 01.07.2017 № 148-ФЗ)\n9) беспрепятственно входить в жилые и иные принадлежащие гражданам помещения и на принадлежащие им земельные участки, на территории и в помещения организаций при пресечении преступлений, создающих угрозу безопасности объектов государственной охраны, а также при преследовании лиц, подозреваемых в совершении таких преступлений, если промедление может создать реальную угрозу безопасности объектов государственной охраны. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nО всех случаях вхождения в жилые и иные помещения против воли проживающих в них граждан органы государственной охраны уведомляют прокурора в течение 24 часов; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n10) принимать при необходимости меры по временному ограничению или запрещению движения транспортных средств и пешеходов на трассах проезда (передвижения) объектов государственной охраны, на улицах и дорогах, по недопущению транспортных средств и граждан на отдельные участки местности и объекты, а также по отбуксировке транспортных средств; (В редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n10.1) обеспечивать соблюдение особых условий использования зон охраняемых объектов.\nОпределение границ зон охраняемых объектов и согласование с федеральным органом исполнительной власти в области государственной охраны градостроительных регламентов для таких зон осуществляются в порядке, установленном Правительством Российской Федерации;\n(Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n10.2) приостанавливать производство работ, осуществление хозяйственной и иной деятельности на охраняемых объектах, в зонах охраняемых объектов, а также на трассах проезда (передвижения) объектов государственной охраны и прилегающих к ним территориях (акваториях) до устранения причин и условий, порождающих угрозу безопасности объектов государственной охраны или охраняемых объектов либо препятствующих защите охраняемых объектов или поддержанию необходимых условий для их функционирования; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n10.3) обеспечивать охрану находящихся на стоянке воздушных судов и иных транспортных средств, используемых в целях транспортного обслуживания и (или) обеспечения безопасности объектов государственной охраны; (Дополнение подпунктом - Федеральный закон от 01.07.2017 № 148-ФЗ)\n10.4) пресекать функционирование беспилотных воздушных, подводных и надводных судов и аппаратов, беспилотных транспортных средств и иных автоматизированных беспилотных комплексов (далее - беспилотные аппараты) в целях обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов, отражения нападения либо угрозы нападения на сотрудников органов государственной охраны и транспортные средства, в том числе посредством подавления или преобразования сигналов дистанционного управления беспилотными аппаратами, воздействия на их пульты управления, а также повреждения или уничтожения беспилотных аппаратов.\nПорядок принятия решения о пресечении функционирования беспилотных аппаратов в указанных целях, а также перечень должностных лиц органов государственной охраны, уполномоченных на принятие такого решения, определяется руководителем федерального органа исполнительной власти в области государственной охраны;\n(Дополнение подпунктом - Федеральный закон от 02.12.2019 № 404-ФЗ) (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n11) получать безвозмездно необходимую информацию от государственных органов, органов местного самоуправления и организаций, а также от общественных объединений, в том числе с использованием единой системы межведомственного электронного взаимодействия (при наличии технической возможности и с соблюдением мер по обеспечению конфиденциальности и безопасности передаваемой информации); (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.07.2017 № 148-ФЗ, от 01.04.2020 № 92-ФЗ, от 01.04.2025 № 41-ФЗ)\n12) разрешать сотрудникам органов государственной охраны хранение и ношение оружия и специальных средств; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ; от 01.07.2017 № 148-ФЗ)\n12.1) самостоятельно осуществлять отбор (в том числе на конкурсной основе) кандидатов для поступления на военную службу по контракту в органы государственной охраны; (Дополнение подпунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n12.2) определять в пределах своих полномочий требования:\nк созданию, построению, эксплуатации и развитию сетей связи специального назначения, предназначенных для нужд органов государственной власти, управлению такими сетями, организационно-техническому обеспечению их устойчивого функционирования и техническим средствам, применяемым в них;\nк информационной безопасности сетей связи специального назначения, предназначенных для нужд органов государственной власти, по согласованию с уполномоченными федеральными органами исполнительной власти в части их компетенции;\nк построению, развитию и эксплуатации средств и систем усиления охраны и иных технических средств и систем на охраняемых объектах;\n(Дополнение подпунктом - Федеральный закон от 08.08.2024 № 271-ФЗ)\n13) использовать в целях обеспечения государственной защиты, в том числе зашифровки, сведений о сотрудниках органов государственной охраны, ведомственной принадлежности их подразделений, помещений и транспортных средств документы иных федеральных органов государственной власти, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, организаций и обрабатывать сведения о сотрудниках органов государственной охраны, содержащиеся в информационных системах и (или) базах данных; (В редакции Федерального закона от 28.02.2025 № 23-ФЗ)\n14) принимать в пределах своих полномочий предусмотренные федеральными законами, а также иными нормативными правовыми актами Российской Федерации меры государственной защиты жизни, здоровья и имущества сотрудников органов государственной охраны, их близких родственников, а в исключительных случаях также иных лиц, на жизнь, здоровье и имущество которых совершается посягательство с целью воспрепятствовать законной деятельности сотрудников органов государственной охраны либо принудить их к изменению ее характера, а равно из мести за указанную деятельность; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n14.1) принимать меры по защите персональных данных объектов государственной охраны и членов их семей, в том числе путем направления владельцам информационных систем и (или) баз данных обязательных для исполнения предписаний о предоставлении доступа к информационным системам и (или) базам данных, содержащим сведения об объектах государственной охраны и о членах их семей, в целях обработки содержащихся в них персональных данных указанных лиц, а также внесения в информационные системы и (или) базы данных ранее не учтенных персональных данных указанных лиц. Форма такого предписания, порядок предоставления доступа к соответствующим информационным системам и (или) базам данных, обработки содержащихся в них персональных данных объектов государственной охраны и членов их семей устанавливаются совместным нормативным правовым актом федерального органа исполнительной власти в области государственной охраны, федерального органа исполнительной власти в области обеспечения безопасности, федерального органа исполнительной власти в области внешней разведки, федерального органа исполнительной власти в области обороны, федерального органа исполнительной власти в сфере внутренних дел. Перечень должностных лиц органов государственной охраны, уполномоченных получать доступ к персональным данным указанных лиц и осуществлять обработку таких персональных данных, определяется руководителем федерального органа исполнительной власти в области государственной охраны. Обязанность по сохранению обрабатываемых персональных данных объектов государственной охраны и членов их семей и ответственность за неправомерное использование или утрату персональных данных объектов государственной охраны и членов их семей возлагаются на лицо, осуществившее их обработку. Обработка персональных данных объектов государственной охраны и членов их семей осуществляется с их согласия и (или) с согласия органов государственной охраны, за исключением персональных данных, подлежащих опубликованию или обязательному раскрытию в соответствии с федеральными законами; (Дополнение подпунктом - Федеральный закон от 01.07.2017 № 148-ФЗ)(В редакции Федерального закона от 28.02.2025 № 23-ФЗ)\n15) организовывать и (или) осуществлять на возмездной или безвозмездной основе подготовку кадров для специальных служб иностранных государств, если это не противоречит принципам осуществления государственной охраны; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ; от 01.07.2017 № 148-ФЗ)\n16) обмениваться со специальными службами, с правоохранительными органами и организациями иностранных государств в пределах своих полномочий оперативной информацией, специальными техническими и иными средствами, а также договариваться об условиях и о порядке обеспечения личной безопасности объектов государственной охраны при их выезде за пределы территории Российской Федерации."],
["16","Взаимодействие органов государственной охраны с организациями Российской Федерации и организациями иностранных государств","","2020-04-01","Статья 16. Взаимодействие органов государственной охраны с организациями Российской Федерации и организациями иностранных государств\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1. Органы государственной охраны обеспечивают безопасность объектов государственной охраны, защиту охраняемых объектов, функционирование связи для нужд органов государственной власти и федеральных информационных систем, находящихся во владении или в пользовании органов государственной охраны, во взаимодействии с государственными органами, органами местного самоуправления и организациями. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nПорядок взаимодействия органов государственной охраны с другими государственными органами, органами местного самоуправления и организациями устанавливается нормативными правовыми актами Российской Федерации, а также соглашениями между указанными органами и организациями. (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n2. В целях решения задач государственной охраны военнослужащие органов государственной охраны могут быть прикомандированы к государственным органам и организациям в порядке, установленном Президентом Российской Федерации, с оставлением их на военной службе. (В редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n3. Органы государственной охраны организуют в пределах своих полномочий взаимодействие участвующих в обеспечении государственной охраны государственных органов и координируют их деятельность по осуществлению мер государственной охраны. (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.04.2020 № 92-ФЗ)\n4. Государственные органы, органы местного самоуправления, организации, общественные объединения обязаны оказывать содействие органам государственной охраны при решении возложенных на органы государственной охраны задач. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5. Взаимодействие органов государственной охраны со специальными службами, с правоохранительными органами и организациями иностранных государств устанавливается на основе международных договоров Российской Федерации и взаимной договоренности. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["17","Защита сведений об органах государственной охраны","","2024-08-08","Статья 17. Защита сведений об органах государственной охраны\n1. Доступ к информации о деятельности органов государственной охраны осуществляется в соответствии с законодательством Российской Федерации с учетом особенностей, установленных настоящим Федеральным законом и актами Президента Российской Федерации.\n2. Сведения о военнослужащих, федеральных государственных гражданских служащих, работниках органов государственной охраны, лицах, уволенных из органов государственной охраны, гражданах, поступающих на военную службу по контракту, на федеральную государственную гражданскую службу или на работу в органы государственной охраны, лицах, оказывающих или оказывавших им содействие на конфиденциальной основе, могут передаваться органами государственной охраны другим государственным органам, иным организациям и гражданам только в случаях, предусмотренных федеральными законами. В остальных случаях указанные сведения могут передаваться на основании решения руководителя федерального органа исполнительной власти в области государственной охраны или уполномоченного им должностного лица.\n3. Физическим лицам может быть отказано в доступе к сведениям об органах государственной охраны, составляющим государственную и иную охраняемую законом тайну, по основаниям, предусмотренным законодательством Российской Федерации о государственной и иной охраняемой законом тайне, либо по соображениям собственной безопасности органов государственной охраны.\n4. Физические лица допускаются к сведениям, полученным в результате осуществления деятельности по обеспечению безопасности объектов государственной охраны и защите охраняемых объектов, осуществляемой органами государственной охраны, в порядке, определяемом руководителем федерального органа исполнительной власти в области государственной охраны.\n5. Лица, получившие в связи с исполнением служебных или профессиональных обязанностей доступ к информации, составляющей профессиональную тайну федерального органа исполнительной власти в области государственной охраны, обязаны соблюдать конфиденциальность данной информации и требования к ее защите.\n6. К профессиональной тайне федерального органа исполнительной власти в области государственной охраны относится информация, не содержащая сведений, составляющих государственную и иную охраняемую законом тайну, разглашение (распространение) которой может создать угрозу безопасности объектов государственной охраны и охраняемых объектов либо угрозу собственной безопасности органов государственной охраны.\n7. Перечень информации, составляющей профессиональную тайну федерального органа исполнительной власти в области государственной охраны, а также требования к ее защите устанавливаются руководителем федерального органа исполнительной власти в области государственной охраны.\n8. Лица, получившие в связи с исполнением служебных или профессиональных обязанностей доступ к информации о деятельности федерального органа исполнительной власти в области государственной охраны, составляющей профессиональную тайну федерального органа исполнительной власти в области государственной охраны, и допустившие разглашение (распространение) такой информации, несут ответственность, предусмотренную законодательством Российской Федерации.\n9. Документы и материалы, содержащие сведения о сотрудниках органов государственной охраны, о лицах, оказывающих или оказывавших им содействие на конфиденциальной основе, а также об организации, о тактике, методах и средствах осуществления деятельности органов государственной охраны, подлежат хранению в органах государственной охраны.\n10. Материалы архива федерального органа исполнительной власти в области государственной охраны, представляющие историческую и научную ценность, рассекреченные в соответствии с федеральным законодательством, передаются на хранение в архивы уполномоченного федерального органа исполнительной власти в сфере архивного дела и делопроизводства в порядке, установленном федеральным законодательством.\n(Статья в редакции Федерального закона от 08.08.2024 № 271-ФЗ)"],
["18","Комплектование органов государственной охраны","","2024-08-08","Статья 18. Комплектование органов государственной охраны\n1. В органах государственной охраны предусмотрены военная служба и федеральная государственная гражданская служба.\n2. Органы государственной охраны комплектуются военнослужащими и гражданским персоналом (федеральными государственными гражданскими служащими и работниками). Военнослужащим, федеральным государственным гражданским служащим, работником органов государственной охраны может быть гражданин Российской Федерации, не имеющий гражданства (подданства) иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства.\n3. Военнослужащие и гражданский персонал органов государственной охраны обязаны сообщить в письменной форме непосредственному начальнику о прекращении гражданства Российской Федерации или приобретении гражданства (подданства) иностранного государства либо получении вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства, в день, когда военнослужащему, федеральному государственному гражданскому служащему, работнику стало известно об этом, но не позднее пяти рабочих дней со дня прекращения гражданства Российской Федерации или приобретения гражданства (подданства) иностранного государства либо получения вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства.\n4. Несоответствие гражданина Российской Федерации требованиям, установленным пунктом 2 настоящей статьи, служит основанием для отказа в приеме (переводе) его на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны, а также для его увольнения с военной службы (со службы, с работы) из органов государственной охраны.\n5. Численность военнослужащих и гражданского персонала органов государственной охраны устанавливает Президент Российской Федерации.\n6. В целях обеспечения собственной безопасности органов государственной охраны военнослужащие и гражданский персонал органов государственной охраны проходят:\n1) психофизиологические исследования, тестирования на предмет употребления наркотических средств и психотропных веществ, наличия у них алкогольной, наркотической или иной токсической зависимости, проверку в целях определения их пригодности к военной службе, к федеральной государственной гражданской службе или к работе в органах государственной охраны и соответствия квалификационным требованиям, в том числе опрос с использованием технических и иных средств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде;\n2) проверку, связанную с обеспечением собственной безопасности органов государственной охраны, в том числе с использованием технических и иных средств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде.\n7. Граждане Российской Федерации, поступающие на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны, проходят:\n1) отбор, исследование достоверности сообщаемых ими сведений и выявление обстоятельств, препятствующих их приему на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны;\n2) психофизиологические исследования, тестирования на предмет употребления наркотических средств и психотропных веществ, наличия у них алкогольной, наркотической или иной токсической зависимости, проверку в целях определения их пригодности к военной службе, к федеральной государственной гражданской службе или к работе в органах государственной охраны и соответствия квалификационным требованиям, в том числе опрос с использованием технических и иных средств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде;\n3) проверку, связанную с обеспечением собственной безопасности органов государственной охраны, в том числе с использованием технических и иных средств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде;\n4) процедуру оформления допуска к сведениям, составляющим государственную тайну.\n8. Отбор, исследования, тестирования и проверки, указанные в пунктах 6 и 7 настоящей статьи, проводятся в порядке, определяемом руководителем федерального органа исполнительной власти в области государственной охраны.\n9. Согласие граждан Российской Федерации, поступающих на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны, на прохождение исследований, тестирований и проверок, указанных в настоящей статье, закрепляется в заявлении о приеме на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны. Согласие военнослужащих и гражданского персонала органов государственной охраны на прохождение в период службы или работы исследований, тестирований и проверок, указанных в настоящей статье, закрепляется соответственно в контракте о прохождении военной службы, служебном контракте, трудовом договоре.\n10. Граждане Российской Федерации, поступающие на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны, военнослужащие и гражданский персонал органов государственной охраны обязаны представлять информацию, относящуюся к обеспечению собственной безопасности органов государственной охраны, в соответствии с перечнем и в порядке, которые определяются руководителем федерального органа исполнительной власти в области государственной охраны.\n11. Граждане Российской Федерации не могут быть приняты на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны, а военнослужащие, проходящие военную службу по контракту, и гражданский персонал органов государственной охраны могут быть уволены со службы или с работы по основаниям, предусмотренным законодательством Российской Федерации, либо в случае:\n1) отказа от прохождения государственной дактилоскопической регистрации, процедуры проверки или оформления допуска к сведениям, составляющим государственную тайну, опроса с использованием технических и иных средств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде, обследования на предмет употребления наркотических средств и психотропных веществ;\n2) если они имеют судимость или имели судимость, которая снята или погашена, либо если в отношении их осуществляется уголовное преследование, либо если в отношении их уголовное дело или уголовное преследование прекращено по основаниям, не дающим право на реабилитацию;\n3) непредставления документов или сведений, подлежащих представлению в соответствии с нормативными правовыми актами Российской Федерации или правовыми актами федерального органа исполнительной власти в области государственной охраны, либо представления подложных документов или заведомо ложных сведений;\n4) наличия зарегистрированного за пределами Российской Федерации права собственности на имущество;\n5) если они являются членами политических партий и иных общественных объединений, преследующих политические цели, и (или) участвуют в их деятельности;\n6) если они занимаются предпринимательской деятельностью;\n7) употребления ими наркотических средств или психотропных веществ без назначения врача либо новых потенциально опасных психоактивных веществ;\n8) если они признаны иностранными агентами.\n12. Сведения об основании для отказа в приеме на военную службу, на федеральную государственную гражданскую службу или на работу в органы государственной охраны представляются гражданину с учетом законодательства Российской Федерации о государственной и иной охраняемой законом тайне.\n13. Военнослужащим и гражданскому персоналу органов государственной охраны запрещается устанавливать (поддерживать) контакты с лицами, в отношении которых заведомо известно, что они являются иностранными гражданами и (или) признаны иностранными агентами, обращаться в зарубежные средства массовой информации, иностранные, международные организации, а также в организации и объединения, признанные иностранными агентами, за исключением случаев, предусмотренных нормативными правовыми актами федерального органа исполнительной власти в области государственной охраны.\n14. Военнослужащим органов государственной охраны, проходящим военную службу по контракту, гражданскому персоналу органов государственной охраны, их супругам и несовершеннолетним детям запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации, владеть и (или) пользоваться иностранными финансовыми инструментами. При этом понятие \"иностранные финансовые инструменты\" используется в настоящем Федеральном законе в значении, определенном Федеральным законом от 7 мая 2013 года № 79-ФЗ \"О запрете отдельным категориям лиц открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации, владеть и (или) пользоваться иностранными финансовыми инструментами\".\n15. Военнослужащие и гражданский персонал органов государственной охраны, имеющие зарегистрированное за пределами Российской Федерации право собственности на имущество, обязаны в срок, определенный руководителем федерального органа исполнительной власти в области государственной охраны, принять меры по его отчуждению. В случае невозможности принятия таких мер в связи с арестом, запретом распоряжения, наложенными компетентными органами иностранного государства в соответствии с законодательством того иностранного государства, на территории которого находится имущество, или в связи с иными обстоятельствами, не зависящими от воли указанных лиц, такие меры должны быть приняты в течение одного года со дня, когда стало возможно их принятие. Каждый случай невыполнения таких требований подлежит рассмотрению в установленном порядке на заседании аттестационной комиссии.\n16. Военнослужащим и гражданскому персоналу органов государственной охраны запрещается размещать в средствах массовой информации, в информационных системах и информационно-телекоммуникационных сетях, не предназначенных для обработки сведений, составляющих государственную и иную охраняемую законом тайну, информацию (в том числе фото-, видеоматериалы и другие материалы) о себе, других военнослужащих и лицах из числа гражданского персонала органов государственной охраны (в том числе о лицах, уволенных с военной службы, со службы, с работы), позволяющую раскрыть принадлежность к органам государственной охраны, о своей (об их) служебной (трудовой) деятельности, деятельности органов государственной охраны, а также об объектах государственной охраны и (или) охраняемых объектах, за исключением случаев, предусмотренных нормативными правовыми актами Российской Федерации, нормативными правовыми актами федерального органа исполнительной власти в области государственной охраны.\n(Статья в редакции Федерального закона от 08.08.2024 № 271-ФЗ)"],
["19","Сотрудники органов государственной охраны","","2017-07-01","Статья 19. Сотрудники органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1. Военнослужащие органов государственной охраны (за исключением военнослужащих, проходящих военную службу по призыву), а также лица из числа гражданского персонала, назначенные на воинские должности, являются сотрудниками органов государственной охраны. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n2. (Пункт утратил силу - Федеральный закон от 01.07.2017 № 148-ФЗ)\n3. (Пункт утратил силу - Федеральный закон от 01.07.2017 № 148-ФЗ)\n4. Сотрудники органов государственной охраны при исполнении ими служебных обязанностей являются представителями власти и находятся под защитой государства. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nЗаконные требования сотрудников органов государственной охраны обязательны для исполнения гражданами и должностными лицами. Воспрепятствование исполнению сотрудниками служебных обязанностей, оскорбление их чести и достоинства, оказание сопротивления, угроза или насилие в отношении сотрудников органов государственной охраны, посягательство на их жизнь, здоровье и имущество в связи с исполнением указанными сотрудниками служебных обязанностей влекут за собой ответственность, установленную федеральным законодательством. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nЗапрещается привлекать сотрудников органов государственной охраны для выполнения функций, не относящихся к их служебным обязанностям. Никто, кроме прямых и непосредственных начальников, не вправе вмешиваться в служебную деятельность сотрудников органов государственной охраны. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nАбзац. (Утратил силу - Федеральный закон от 01.07.2017 № 148-ФЗ)\nАбзац. (Утратил силу - Федеральный закон от 01.07.2017 № 148-ФЗ)\n5. Военнослужащие и гражданский персонал органов государственной охраны подлежат обязательной государственной дактилоскопической регистрации в соответствии с законодательством Российской Федерации. (Дополнение пунктом - Федеральный закон от 07.11.2000 № 135-ФЗ) (В редакции федеральных законов от 08.12.2011 № 424-ФЗ; от 01.07.2017 № 148-ФЗ)"],
["19.1","Служба в органах государственной охраны","","2026-06-10","Статья 19.1. Служба в органах государственной охраны\n1. Военнослужащие органов государственной охраны проходят военную службу в соответствии с законодательством Российской Федерации о прохождении военной службы с учетом установленных настоящим Федеральным законом особенностей, обусловленных спецификой задач, стоящих перед органами государственной охраны, и обязанностей, возложенных на них.\n2. Сотрудники органов государственной охраны по своим личным, профессиональным и психологическим качествам, образованию и состоянию здоровья должны соответствовать требованиям, предъявляемым к ним при исполнении возложенных на них обязанностей, и обязаны соблюдать кодекс этики и служебного поведения сотрудников органов государственной охраны. Квалификационные требования к уровню образования, стажу, профессиональным знаниям и навыкам, необходимым для исполнения сотрудниками органов государственной охраны своих должностных обязанностей, и кодекс этики и служебного поведения сотрудников органов государственной охраны утверждаются руководителем федерального органа исполнительной власти в области государственной охраны.\n3. Совершение сотрудниками органов государственной охраны при исполнении служебных обязанностей либо во внеслужебное время виновных действий (бездействия), в результате которых были нарушены положения настоящего Федерального закона и (или) кодекса этики и служебного поведения сотрудников органов государственной охраны, либо несоответствие сотрудников органов государственной охраны одному из предусмотренных пунктом 2 настоящей статьи требований к их личным, профессиональным и психологическим качествам, образованию, состоянию здоровья или иным требованиям, установленным настоящим Федеральным законом, может служить основанием для увольнения со службы или с работы в органах государственной охраны.\n4. (Пункт утратил силу - Федеральный закон от 08.08.2024 № 271-ФЗ)\n5. Для сотрудников органов государственной охраны, замещающих должности руководителей (начальников, командиров) и заместителей руководителей (начальников, командиров), устанавливается ненормированный служебный день. Руководителем федерального органа исполнительной власти в области государственной охраны или уполномоченным руководителем (начальником) ненормированный служебный день может устанавливаться для сотрудников, замещающих иные должности, определяемые перечнем должностей в органах государственной охраны, утверждаемым руководителем федерального органа исполнительной власти в области государственной охраны. Сотрудникам, для которых установлен ненормированный служебный день, предоставляется ежегодный дополнительный отпуск в соответствии с законодательством Российской Федерации.\n6. С гражданами Российской Федерации, проходившими военную службу по контракту, являющимися высококвалифицированными специалистами и достигшими предельного возраста пребывания на военной службе, может быть заключен новый контракт о прохождении военной службы в порядке, определяемом руководителем федерального органа исполнительной власти в области государственной охраны, либо, если указанные граждане имеют воинские звания высших офицеров, в порядке, определяемом Президентом Российской Федерации. (Дополнение пунктом - Федеральный закон от 08.08.2024 № 271-ФЗ)\n7. Полномочия должностных лиц органов государственной охраны на применение поощрений и дисциплинарных взысканий в отношении подчиненных им военнослужащих устанавливаются руководителем федерального органа исполнительной власти в области государственной охраны. (Дополнение пунктом - Федеральный закон от 10.06.2026 № 177-ФЗ)\n(Дополнение статьей - Федеральный закон от 01.07.2017 № 148-ФЗ)"],
["19.2","Служебное удостоверение","","2017-07-01","Статья 19.2. Служебное удостоверение\n1. Служебное удостоверение сотрудника органов государственной охраны является документом, подтверждающим личность, должность, права и полномочия, предоставленные сотруднику органов государственной охраны настоящим Федеральным законом, другими федеральными законами и иными нормативными правовыми актами Российской Федерации, а также право на хранение и ношение оружия и специальных средств.\n2. Образцы служебных удостоверений и порядок их выдачи определяются руководителем федерального органа исполнительной власти в области государственной охраны.\n(Дополнение статьей - Федеральный закон от 01.07.2017 № 148-ФЗ)"],
["19.3","Особенности обработки персональных данных сотрудников органов государственной охраны и отдельных категорий лиц","","2025-02-28","Статья 19.3. Особенности обработки персональных данных сотрудников органов государственной охраны и отдельных категорий лиц\nВ целях обеспечения безопасности содержащихся в информационных системах и (или) базах данных сведений о сотрудниках органов государственной охраны, лицах, оказывающих или оказывавших им содействие на конфиденциальной основе, лицах, в отношении которых органами государственной охраны применяются меры государственной защиты, орган государственной охраны вправе направить владельцу информационной системы и (или) базы данных обязательное для исполнения предписание о предоставлении доступа к соответствующим информационным системам и (или) базам данных для обработки содержащихся в них персональных данных сотрудников и лиц, указанных в настоящей статье, а также внесения в информационные системы и (или) базы данных ранее не учтенных персональных данных сотрудников и лиц, указанных в настоящей статье. Форма такого предписания, порядок предоставления доступа к соответствующим информационным системам и (или) базам данных, обработки содержащихся в них персональных данных сотрудников и лиц, указанных в настоящей статье, устанавливаются совместным нормативным правовым актом федерального органа исполнительной власти в области государственной охраны, федерального органа исполнительной власти в области обеспечения безопасности, федерального органа исполнительной власти в области внешней разведки, федерального органа исполнительной власти в области обороны, федерального органа исполнительной власти в сфере внутренних дел. Перечень должностных лиц органов государственной охраны, которые вправе получать доступ к персональным данным сотрудников и лиц, указанных в настоящей статье, и осуществлять обработку таких персональных данных, определяется руководителем федерального органа исполнительной власти в области государственной охраны. Обязанность по сохранению обрабатываемых персональных данных сотрудников и лиц, указанных в настоящей статье, и ответственность за неправомерное использование или утрату персональных данных сотрудников и лиц, указанных в настоящей статье, возлагаются на лицо, осуществившее их обработку.\n(Дополнение статьей - Федеральный закон от 28.02.2025 № 23-ФЗ)"],
["20","Гарантии правовой и социальной защиты сотрудников органов государственной охраны","","2026-06-10","Статья 20. Гарантии правовой и социальной защиты сотрудников органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1. При исполнении сотрудником органов государственной охраны служебных обязанностей не допускаются применение к нему административных наказаний, его привод и административное задержание, а также личный досмотр, досмотр находящихся при нем вещей, досмотр используемых им транспортных средств без представителя соответствующего органа государственной охраны или без решения суда. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nЗащита жизни и здоровья, чести и достоинства, а также имущества сотрудника органов государственной охраны и членов его семьи от преступных посягательств в связи с исполнением им служебных обязанностей осуществляется в порядке, установленном федеральным законодательством. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n2. На военнослужащих органов государственной охраны распространяются гарантии правовой и социальной защиты, установленные федеральным законодательством в отношении военнослужащих. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nВоеннослужащим органов государственной охраны зачет времени военной службы в льготном исчислении для назначения пенсии и исчисления ежемесячной надбавки за выслугу лет производится по основаниям, определяемым Правительством Российской Федерации. (В редакции федеральных законов от 08.12.2011 № 424-ФЗ; от 01.07.2017 № 148-ФЗ)\nВоеннослужащим органов государственной охраны из числа высококвалифицированных специалистов в выслугу лет для назначения пенсии и исчисления ежемесячной надбавки за выслугу лет может засчитываться стаж их трудовой деятельности до зачисления на военную службу в порядке, определяемом руководителем федерального органа исполнительной власти в области государственной охраны. (В редакции федеральных законов от 08.12.2011 № 424-ФЗ; от 01.07.2017 № 148-ФЗ)\nАбзац. (Исключен - Федеральный закон от 07.05.2002 № 49-ФЗ)\n3. Сотрудники органов государственной охраны, их близкие родственники, а в исключительных случаях также иные лица, на жизнь, здоровье и имущество которых совершается посягательство с целью воспрепятствовать законной деятельности сотрудников органов государственной охраны либо принудить их к изменению ее характера, а равно из мести за указанную деятельность, имеют право на государственную защиту, если их жизнь, здоровье и имущество находятся под угрозой в связи с исполнением указанными сотрудниками служебных обязанностей. Порядок и условия предоставления государственной защиты определяются настоящим Федеральным законом, другими федеральными законами, а также иными нормативными правовыми актами Российской Федерации. В случае, если каким-либо из перечисленных нормативных актов установлены иные условия государственного личного, имущественного страхования или компенсационных выплат в отношении сотрудников органов государственной охраны, применяются условия, установленные только в одном акте, по выбору получателя. (В редакции федеральных законов от 22.08.2004 № 122-ФЗ; от 08.12.2011 № 424-ФЗ)\n4. Обеспечение жилыми помещениями специализированного жилищного фонда военнослужащих органов государственной охраны, выполняющих задачи по обеспечению организации и функционирования связи для нужд органов государственной власти на отдельных объектах федеральных органов исполнительной власти, и проживающих совместно с ними членов их семей осуществляется федеральными органами исполнительной власти, в ведении которых находятся такие объекты.\nПеречень таких объектов и порядок обеспечения жилыми помещениями специализированного жилищного фонда указанных военнослужащих и проживающих совместно с ними членов их семей определяются нормативным правовым актом, издаваемым соответствующим федеральным органом исполнительной власти, в ведении которого находятся такие объекты, совместно с федеральным органом исполнительной власти в области государственной охраны.\n(Дополнение пунктом - Федеральный закон от 10.06.2026 № 177-ФЗ)"],
["21","Гражданский персонал органов государственной охраны","","2013-11-25","Статья 21. Гражданский персонал органов государственной охраны\n1. Федеральные государственные гражданские служащие органов государственной охраны проходят федеральную государственную гражданскую службу в соответствии с федеральным законодательством о государственной гражданской службе, трудовым законодательством и настоящим Федеральным законом.\n2. Государственные гарантии трудовых прав и свобод, создание благоприятных условий труда, защита прав и интересов работников органов государственной охраны осуществляются на основании трудового законодательства.\n3. Гражданскому персоналу органов государственной охраны запрещается заниматься предпринимательской деятельностью.\n4. Гражданский персонал органов государственной охраны, а также дети, не достигшие возраста 18 лет, лиц из числа гражданского персонала имеют право на медицинскую помощь в военно-медицинских подразделениях и организациях органов федеральной службы безопасности. (В редакции Федерального закона от 25.11.2013 № 317-ФЗ)\n(Статья в редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["22","Ответственность сотрудников органов государственной охраны","","2011-12-08","Статья 22. Ответственность сотрудников органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nНеисполнение или ненадлежащее исполнение сотрудниками органов государственной охраны служебных обязанностей, а также распространение ими информации (персональных данных) об объектах государственной охраны и иных гражданах, ставшей известной в связи с исполнением ими служебных обязанностей, влечет за собой ответственность, предусмотренную федеральным законодательством. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n(Статья в редакции Федерального закона от 18.07.1997 № 101-ФЗ)"],
["23","Обжалование неправомерных действий сотрудников органов государственной охраны","","2011-12-08","Статья 23. Обжалование неправомерных действий сотрудников органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nГраждане и должностные лица вправе обжаловать действия сотрудников органов государственной охраны должностным лицам этих органов, прокурору или в суд, если считают, что эти действия повлекли ущемление их прав, или нанесли им моральный вред, или причинили им убытки. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["24","Порядок применения физической силы, специальных средств, оружия и боевой техники","","2020-04-01","Статья 24. Порядок применения физической силы, специальных средств, оружия и боевой техники\n(Наименование в редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n1. Сотрудники органов государственной охраны имеют право на применение физической силы, специальных средств, оружия и боевой техники лично или в составе подразделения (группы), а командиры (начальники) имеют право отдавать приказы об их применении в случаях и порядке, которые предусмотрены настоящим Федеральным законом и иными нормативными правовыми актами Российской Федерации.\nПрименение сотрудниками органов государственной охраны боевой техники осуществляется в порядке, определяемом Правительством Российской Федерации.\n(Пункт в редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n2. Сотрудники органов государственной охраны перед применением физической силы, специальных средств или оружия обязаны сообщить лицам, в отношении которых предполагается применение физической силы, специальных средств или оружия, о том, что они являются сотрудниками органов государственной охраны, предупредить их о своем намерении и предоставить им возможность и время для выполнения законных требований сотрудников органов государственной охраны, за исключением случаев, если: (В редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n1) промедление в применении физической силы, специальных средств или оружия создает непосредственную опасность для жизни или здоровья объектов государственной охраны, сотрудников органов государственной охраны, сотрудников (военнослужащих) государственных органов, участвующих в пределах своих полномочий в обеспечении государственной охраны, военнослужащих, проходящих военную службу по призыву в органах государственной охраны и привлеченных для обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов, а также иных граждан либо реальную угрозу безопасности охраняемых объектов и транспортных средств; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.04.2020 № 92-ФЗ)\n2) такое предупреждение является неуместным или невозможным.\n2.1. Сотрудники органов государственной охраны имеют право обнажить оружие и привести его в готовность, если в создавшейся обстановке могут возникнуть основания для его применения, предусмотренные статьей 27 настоящего Федерального закона.\nПри попытке лица, задерживаемого сотрудником органов государственной охраны с обнаженным оружием, приблизиться к сотруднику органов государственной охраны, сократив при этом указанное им расстояние, или прикоснуться к его оружию сотрудник органов государственной охраны имеет право применить оружие в соответствии с пунктом 1 статьи 27 настоящего Федерального закона.\n(Дополнение пунктом - Федеральный закон от 01.07.2017 № 148-ФЗ)\n3. Сотрудники органов государственной охраны не несут ответственность за вред и убытки, причиненные лицам и организациям при применении физической силы, специальных средств, оружия и боевой техники, если применение физической силы, специальных средств, оружия и боевой техники осуществлялось в случаях и порядке, которые предусмотрены настоящим Федеральным законом и иными нормативными правовыми актами Российской Федерации. (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n3.1. В состоянии необходимой обороны или крайней необходимости сотрудники органов государственной охраны при отсутствии либо невозможности (нецелесообразности) применения специальных средств или оружия вправе использовать любые подручные средства (в том числе транспортные). (Дополнение пунктом - Федеральный закон от 01.04.2020 № 92-ФЗ)\n4. Руководитель подразделения соответствующего органа государственной охраны уведомляет прокурора о всех случаях смерти или ранения лица, в отношении которого были применены физическая сила, специальные средства или оружие. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5. Сотрудники (военнослужащие) государственных органов, участвующих в пределах своих полномочий в обеспечении государственной охраны, а также военнослужащие, проходящие военную службу по призыву в органах государственной охраны и привлеченные для обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов, имеют право применять физическую силу, специальные средства, оружие и боевую технику в случаях и порядке, которые предусмотрены настоящим Федеральным законом для сотрудников органов государственной охраны. (Дополнение пунктом - Федеральный закон от 08.12.2011 № 424-ФЗ) (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)"],
["25","Применение физической силы","","2011-12-08","Статья 25. Применение физической силы\nСотрудники органов государственной охраны имеют право применять физическую силу, в том числе боевые приемы рукопашного боя, для пресечения преступлений и иных правонарушений, задержания лиц, их совершивших, преодоления противодействия законным требованиям сотрудников, если ненасильственные способы не обеспечивают исполнение возложенных на них служебных обязанностей. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["26","Применение специальных средств","","2023-08-04","Статья 26. Применение специальных средств\n1. Сотрудники органов государственной охраны имеют право применять состоящие на вооружении органов государственной охраны специальные средства в случае: (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1) отражения нападения либо угрозы нападения на объекты государственной охраны;\n2) отражения нападения либо угрозы нападения на сотрудников органов государственной охраны, сотрудников (военнослужащих) государственных органов, участвующих в пределах своих полномочий в обеспечении государственной охраны, военнослужащих, проходящих военную службу по призыву в органах государственной охраны и привлеченных для обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов, а также иных граждан или пресечения оказываемого сотрудникам (военнослужащим) сопротивления; (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\n3) отражения нападения либо угрозы нападения на охраняемые объекты и транспортные средства, а равно освобождения их при захвате;\n4) задержания правонарушителей и лиц, в отношении которых имеются достаточные основания полагать, что они намерены оказать вооруженное сопротивление или воспрепятствовать исполнению сотрудниками органов государственной охраны возложенных на них служебных обязанностей, и доставления их в органы внутренних дел Российской Федерации; (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5) пресечения массовых беспорядков и групповых действий, нарушающих деятельность объектов государственной охраны;\n6) необходимости пресечь движение транспортного средства в целях обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов; (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n7) пресечения функционирования беспилотных аппаратов в целях, предусмотренных подпунктом 10.4 статьи 15 настоящего Федерального закона. (Дополнение подпунктом - Федеральный закон от 04.08.2023 № 440-ФЗ)\nКроме того, специальные средства могут применяться в случаях, предусмотренных пунктом 1 статьи 27 настоящего Федерального закона.\n1.1. Органы государственной охраны могут использовать служебных животных в качестве специального средства. (Дополнение пунктом - Федеральный закон от 08.12.2011 № 424-ФЗ)\n2. Запрещается применять специальные средства в отношении женщин с видимыми признаками беременности, а также лиц с явными признаками инвалидности и малолетних, за исключением случаев оказания ими вооруженного сопротивления, совершения группового либо иного нападения, угрожающего жизни и здоровью людей.\n3. (Пункт утратил силу - Федеральный закон от 01.04.2020 № 92-ФЗ)\n4. Перечень специальных средств, состоящих на вооружении органов государственной охраны, устанавливает Президент Российской Федерации или по его поручению Правительство Российской Федерации. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["27","Применение оружия","","2023-08-04","Статья 27. Применение оружия\n(Наименование в редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n1. Сотрудники органов государственной охраны в качестве крайней меры имеют право применять оружие в случае: (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1) защиты объектов государственной охраны от нападения либо угрозы нападения, опасного для их жизни или здоровья;\n2) отражения нападения либо угрозы нападения на сотрудников органов государственной охраны, сотрудников (военнослужащих) государственных органов, участвующих в пределах своих полномочий в обеспечении государственной охраны, военнослужащих, проходящих военную службу по призыву в органах государственной охраны и привлеченных для обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов, если жизнь или здоровье этих сотрудников (военнослужащих) подвергается опасности, а также пресечения попыток завладения их оружием, транспортными средствами и средствами связи; (В редакции федеральных законов от 08.12.2011 № 424-ФЗ, от 01.04.2020 № 92-ФЗ)\n3) отражения нападения либо угрозы нападения на охраняемые объекты и транспортные средства, а равно освобождения их при захвате;\n4) освобождения заложников, пресечения террористических и иных преступных посягательств;\n5) задержания лица, оказывающего вооруженное сопротивление или отказывающегося выполнить законное требование о сдаче оружия, если другими способами и средствами подавить сопротивление, задержать лицо или изъять оружие невозможно;\n6) защиты граждан от нападения, угрожающего их жизни или здоровью, если другими способами и средствами защитить их невозможно.\n2. Сотрудники органов государственной охраны также имеют право применять оружие:\n1) для пресечения движения транспортного средства в целях обеспечения безопасности объектов государственной охраны и защиты охраняемых объектов; (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n2) для обезвреживания животного, угрожающего жизни и здоровью граждан и (или) сотрудников органов государственной охраны;\n3) для производства предупредительного выстрела, подачи сигнала тревоги или вызова помощи путем производства выстрела вверх или в ином безопасном направлении;\n4) для пресечения функционирования беспилотных аппаратов в целях, предусмотренных подпунктом 10.4 статьи 15 настоящего Федерального закона. (Дополнение подпунктом - Федеральный закон от 04.08.2023 № 440-ФЗ)\n(Пункт в редакции Федерального закона от 01.07.2017 № 148-ФЗ)\n3. Запрещается применять оружие в отношении женщин, а также лиц с явными признаками инвалидности и несовершеннолетних, если их возраст очевиден или известен сотруднику, за исключением случаев оказания ими вооруженного сопротивления, совершения вооруженного либо группового нападения, угрожающего жизни людей.\n4. Перечень оружия, состоящего на вооружении органов государственной охраны, устанавливает Президент Российской Федерации или по его поручению Правительство Российской Федерации. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["28","Финансирование органов государственной охраны","","2011-12-08","Статья 28. Финансирование органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nОбеспечение деятельности органов государственной охраны является расходным обязательством Российской Федерации. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n(Статья в редакции Федерального закона от 22.08.2004 № 122-ФЗ)"],
["29","Материально-техническое обеспечение органов государственной охраны","","2020-04-01","Статья 29. Материально-техническое обеспечение органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1. Материально-техническое обеспечение органов государственной охраны и создание обеспечивающей инфраструктуры являются расходными обязательствами Российской Федерации.\nОрганы государственной охраны вправе принимать в соответствии с законодательством Российской Федерации в пользование от других государственных органов, органов местного самоуправления, организаций, общественных объединений, граждан Российской Федерации транспортные средства и иное имущество, необходимые для выполнения задач, возложенных на органы государственной охраны федеральным законодательством. Порядок использования указанного имущества определяется руководителем федерального органа исполнительной власти в области государственной охраны. (В редакции Федерального закона от 01.04.2020 № 92-ФЗ)\nСтроительство, реконструкция и предоставление объектов, предназначенных для расквартирования военнослужащих органов государственной охраны или для размещения органов государственной охраны, осуществляются в соответствии с нормативными правовыми актами Российской Федерации за счет средств федерального бюджета и иных средств.\n(Пункт в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n2. Здания, строения, сооружения, оборудование и другое имущество, находящиеся в оперативном управлении органов государственной охраны; водные объекты, прилегающие к указанным зданиям, строениям, сооружениям; имущество, созданное или приобретенное за счет средств федерального бюджета и иных средств, а также земельные участки, предоставленные органам государственной охраны, являются федеральной собственностью. (В редакции федеральных законов от 26.06.2007 № 118-ФЗ; от 08.12.2011 № 424-ФЗ)\n3. Органы государственной охраны могут иметь жилищный фонд, формируемый в порядке, устанавливаемом Правительством Российской Федерации, в том числе жилые помещения в военных городках, служебные жилые помещения и общежития. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n4. Подразделения, организации, созданные федеральным органом исполнительной власти в области государственной охраны, осуществляют свою деятельность в рамках настоящего Федерального закона без лицензирования и приватизации не подлежат. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n5. (Пункт утратил силу - Федеральный закон от 22.08.2004 № 122-ФЗ)"],
["30","Средства вооружения и оснащения органов государственной охраны","","2011-12-08","Статья 30. Средства вооружения и оснащения органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n1. Органы государственной охраны без лицензирования участвуют в разработке и создании средств вооружения и оснащения, включая специальные технические и иные средства, приобретают и используют средства вооружения и оснащения, включая специальные технические и иные средства, приобретают, в том числе за пределами Российской Федерации, и используют боевое оружие и боеприпасы к нему, принятые на вооружение федерального органа исполнительной власти в области государственной охраны, а также служебное, гражданское оружие и боеприпасы к нему. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n2. Продажа, передача, вывоз за пределы территории Российской Федерации и ввоз на ее территорию средств вооружения и оснащения, включая специальные технические и иные средства, оружия и боеприпасов к нему, которые могут использоваться в деятельности органов государственной охраны, осуществляются указанными органами в порядке, установленном федеральным законодательством. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\n3. Органы государственной охраны разрабатывают, создают и эксплуатируют информационные системы, системы связи и системы передачи данных, а также средства защиты информации, включая средства криптографической защиты, в порядке, установленном нормативными правовыми актами Российской Федерации. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["31","Контроль за деятельностью органов государственной охраны","","2022-08-04","Статья 31. Контроль за деятельностью органов государственной охраны\n(Наименование в редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nКонтроль за деятельностью органов государственной охраны осуществляют Президент Российской Федерации, Федеральное Собрание Российской Федерации, Правительство Российской Федерации и суды в пределах полномочий, определяемых Конституцией Российской Федерации, федеральными конституционными законами и федеральными законами. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nСенаторы Российской Федерации и депутаты Государственной Думы Федерального Собрания Российской Федерации в целях осуществления своих полномочий вправе получать сведения о деятельности органов государственной охраны в порядке, установленном федеральным законодательством. (В редакции Федерального закона от 04.08.2022 № 363-ФЗ)"],
["32","Прокурорский надзор","","2011-12-08","Статья 32. Прокурорский надзор\nНадзор за исполнением законов Российской Федерации органами государственной охраны осуществляют Генеральный прокурор Российской Федерации и уполномоченные им прокуроры. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nСведения о лицах, оказывающих или оказывавших органам государственной охраны содействие на конфиденциальной основе, представляются соответствующему прокурору на основаниях и в порядке, которые установлены законодательством. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)\nСведения об организации, о тактике, методах и средствах осуществления деятельности органов государственной охраны в предмет прокурорского надзора не входят. (В редакции Федерального закона от 08.12.2011 № 424-ФЗ)"],
["33","Правопреемство Федеральной службы охраны Российской Федерации","","","Статья 33. Правопреемство Федеральной службы охраны Российской Федерации\nФедеральная служба охраны Российской Федерации является правопреемником Главного управления охраны Российской Федерации.\nВоеннослужащие и гражданский персонал Главного управления охраны Российской Федерации считаются проходящими военную службу (работающими) в Федеральной службе охраны Российской Федерации в занимаемых должностях без переаттестации и переназначения."],
["34","Вступление настоящего Федерального закона в силу","","","Статья 34. Вступление настоящего Федерального закона в силу\nНастоящий Федеральный закон вступает в силу со дня его официального опубликования."],
["35","О признании утратившими силу отдельных нормативных правовых актов","","","Статья 35. О признании утратившими силу отдельных нормативных правовых актов\nСо дня вступления в силу настоящего Федерального закона признать утратившими силу:\nЗакон Российской Федерации от 28 апреля 1993 года \"О государственной охране высших органов государственной власти Российской Федерации и их должностных лиц\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 21, ст. 745);\nпостановление Верховного Совета Российской Федерации от 28 апреля 1993 года \"О введении в действие Закона Российской Федерации \"О государственной охране высших органов государственной власти Российской Федерации и их должностных лиц\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 21, ст. 746);\nЗакон Российской Федерации от 28 апреля 1993 года \"О государственной охране высших представительных органов государственной власти Российской Федерации\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 27, ст. 1010);\nпостановление Верховного Совета Российской Федерации от 6 марта 1993 года \"О введении в действие Закона Российской Федерации \"О государственной охране высших представительных органов государственной власти Российской Федерации\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 27, ст. 1011);\nпостановление Верховного Совета Российской Федерации от 28 апреля 1993 года \"О повторном рассмотрении Закона Российской Федерации \"О государственной охране высших представительных органов государственной власти Российской Федерации\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 27, ст. 1012)."],
["36","О приведении нормативных правовых актов Российской Федерации в соответствие с настоящим Федеральным законом","","","Статья 36. О приведении нормативных правовых актов Российской Федерации в соответствие с настоящим Федеральным законом\nПредложить Президенту Российской Федерации и поручить Правительству Российской Федерации привести свои нормативные правовые акты в соответствие с настоящим Федеральным законом.\nПрезидент Российской Федерации Б.Ельцин\nМосква, Кремль 27 мая 1996 года № 57-ФЗ"]
];
